INSERT INTO `wp_aioseo_notifications` VALUES
(1,'68967badb8cf1',NULL,'Have you connected your site to Google Search Console?','AIOSEO can now verify whether your site is correctly verified with Google Search Console and that your sitemaps have been submitted correctly. Connect with Google Search Console now to ensure your content is being added to Google as soon as possible for increased rankings.','warning','[\"all\"]',NULL,'search-console-site-not-connected','2025-08-08 22:35:25',NULL,'Connect to Google Search Console','https://route#aioseo-settings&aioseo-scroll=google-search-console-settings&aioseo-highlight=google-search-console-settings:webmaster-tools?activetool=googleSearchConsole',NULL,NULL,0,0,'2025-08-08 22:35:25','2025-08-08 22:35:25'),
(2,'68a8f1e90bfae',NULL,'Email Reports','Stay ahead in SEO with our new email digest! Get the latest tips, trends, and tools delivered right to your inbox, helping you optimize smarter and faster. Enable it today and never miss an update that can take your rankings to the next level.','info','[\"all\"]',NULL,'email-reports-enable-reminder','2025-08-22 22:40:41',NULL,'Enable Email Reports','https://route#aioseo-settings&aioseo-scroll=aioseo-email-summary-row&aioseo-highlight=aioseo-email-summary-row:advanced','All Good, I\'m already getting it','http://action#notification/email-reports-enable',0,1,'2025-08-22 22:40:41','2025-08-22 22:40:41');
